#include <immintrin.h>   // AVX2 intrinsics
float sum_avx2(const float *a, long n) {
    __m256 acc = _mm256_setzero_ps();        // 8 lanes of 0
    long i = 0;
    for (; i + 8 <= n; i += 8)               // main vector loop
        acc = _mm256_add_ps(acc, _mm256_loadu_ps(a + i));
    // horizontal reduction: 8 lanes to 1 float
    __m128 lo = _mm256_castps256_ps128(acc);
    __m128 hi = _mm256_extractf128_ps(acc, 1);
    __m128 s4 = _mm_add_ps(lo, hi);          // 4 lanes
    s4 = _mm_add_ps(s4, _mm_movehl_ps(s4, s4));   // 2 lanes
    s4 = _mm_add_ss(s4, _mm_movehdup_ps(s4));     // 1 lane
    float s = _mm_cvtss_f32(s4);
    for (; i < n; i++)                       // scalar tail
        s += a[i];
    return s;
}

