float sum_avx512(const float *a, long n) {
    __m512 acc = _mm512_setzero_ps();
    for (long i = 0; i < n; i += 16) {
        long rem = n - i;
        __mmask16 k = rem >= 16 ? 0xFFFF : (__mmask16)((1u << rem) - 1);
        acc = _mm512_add_ps(acc, _mm512_maskz_loadu_ps(k, a + i));
    }
    return _mm512_reduce_add_ps(acc);   // horizontal sum helper
}

#include <arm_sve.h>
void saxpy_sve(float *y, const float *x, float a, int64_t n) {
    for (int64_t i = 0; i < n; i += svcntw()) {   // svcntw: floats per vector
        svbool_t pg = svwhilelt_b32(i, n);       // lane j active if i + j < n
        svfloat32_t vx = svld1(pg, x + i);       // inactive lanes not loaded
        svfloat32_t vy = svld1(pg, y + i);
        vy = svmla_x(pg, vy, vx, a);             // vy + vx * a
        svst1(pg, y + i, vy);                    // inactive lanes not stored
    }
}

__attribute__((target_clones("avx512f", "avx2", "default")))
void saxpy(float *restrict y, const float *restrict x, float a, long n) {
    for (long i = 0; i < n; i++) y[i] = a * x[i] + y[i];
