// GCC and Clang build three copies of the loop, one per target,
// plus a resolver that the dynamic loader runs once to pick one.

fn sum(a: &[f32]) -> f32 {
    #[cfg(any(target_arch = "x86", target_arch = "x86_64"))]
    {
        if is_x86_feature_detected!("avx2") {
            return unsafe { sum_avx2(a) };   // safe: we just checked
        }
    }
    sum_fallback(a)
}

#[cfg(any(target_arch = "x86", target_arch = "x86_64"))]
#[target_feature(enable = "avx2")]
unsafe fn sum_avx2(a: &[f32]) -> f32 { sum_fallback(a) } // compiled with AVX2 on

fn sum_fallback(a: &[f32]) -> f32 { a.iter().sum() }
